SELECT COUNT(*) AS brand_new_count
FROM nlq.listings
WHERE condition ILIKE '%new%';

SELECT COUNT(*) AS total_listings_at_iv
FROM nlq.listings
WHERE meetup_spot ILIKE '%International Village%';

SELECT MAX(rent_price_per_week) AS highest_weekly_rent
FROM nlq.listings
WHERE rent_price_per_week IS NOT NULL;

SELECT spot_id, name, area
FROM nlq.meetup_spots
WHERE area = 'on campus';

SELECT ROUND(AVG(rent_deposit)::numeric, 2) AS avg_deposit
FROM nlq.listings
WHERE category = 'bikes_transport';

SELECT COUNT(*) AS board_game_count
FROM nlq.listings
WHERE category ILIKE '%board%';

SELECT round(100.0 * SUM(CASE WHEN rent_price_per_week IS NOT NULL THEN 1 ELSE 0 END) / COUNT(*), 2) AS rent_percentage
FROM nlq.listings
WHERE category = 'electronics';

SELECT ROUND(percentile_cont(0.5) WITHIN GROUP (ORDER BY rent_price_per_week)::numeric, 2) AS median_weekly_rent
FROM nlq.listings
WHERE rent_price_per_week IS NOT NULL;

SELECT COUNT(*) AS pickup_only_count
FROM nlq.listings
WHERE meetup_spot ILIKE '%pickup only%';

SELECT COUNT(*) AS listings_since_oct_1
FROM nlq.listings
WHERE (listed_at AT TIME ZONE 'America/New_York')::date >= DATE '2026-10-01';

SELECT COUNT(*) AS reviews_given
FROM nlq.my_reviews
WHERE direction = 'given';

SELECT COUNT(*) AS five_star_ratings_received
FROM nlq.my_reviews
WHERE direction = 'received' AND rating = 5;

SELECT COUNT(*) AS under_4_star_reviews
FROM nlq.my_reviews
WHERE direction = 'received' AND rating < 4;

SELECT COUNT(DISTINCT category) AS category_count
FROM nlq.my_deals
WHERE my_role = 'buyer' AND deal_type = 'sale' AND status = 'completed';

select coalesce(sum(case when my_role = 'seller' then agreed_price else -agreed_price end), 0) as net_gain
from nlq.my_deals
where status = 'completed';

SELECT MAX(agreed_price) AS max_paid
FROM nlq.deals
WHERE deal_type = 'sale' AND status = 'completed';

SELECT ROUND(AVG(rental_deposit)::numeric, 2) AS avg_deposit
FROM nlq.deals
WHERE deal_type = 'rental' AND rental_deposit IS NOT NULL;

SELECT COUNT(*) AS total_requested_deals
FROM nlq.deals
WHERE status = 'requested';

SELECT ROUND(AVG(agreed_price)::numeric, 2) AS avg_buyer_price
FROM nlq.deals
WHERE deal_type = 'sale' AND status = 'completed';

SELECT COUNT(DISTINCT item_id) AS items_rented_at_least_once
FROM nlq.deals
WHERE deal_type = 'rental' AND status = 'completed';

SELECT ROUND(100.0 * SUM(CASE WHEN status = 'cancelled' THEN 1 ELSE 0 END) / COUNT(*), 2) AS cancelled_percent
FROM nlq.deals
WHERE deal_type = 'sale' AND status IN ('cancelled', 'requested');

SELECT COUNT(*) AS reserved_count
FROM nlq.listings_all
WHERE status = 'reserved';

SELECT COUNT(*) AS suspended_account_count
FROM nlq.students
WHERE account_status = 'suspended';

SELECT COUNT(*) AS resolved_reports
FROM nlq.reports
WHERE status = 'resolved';

SELECT COUNT(*) AS listings_with_four_photos
FROM nlq.listings_all
WHERE photo_count = 4;

SELECT COUNT(*) AS total_1star_reviews
FROM nlq.reviews
WHERE rating = 1;

SELECT COUNT(*) AS report_count
FROM nlq.reports
WHERE target_type = 'listing';

SELECT COUNT(*) AS items_rented_out
FROM nlq.listings_all la
WHERE la.status = 'rented_out';

SELECT category, label
FROM nlq.categories
WHERE category_group = 'leisure';

SELECT ROUND(AVG(buyer_message_count)::numeric, 2) AS avg_buyer_messages,
       ROUND(AVG(seller_message_count)::numeric, 2) AS avg_seller_messages
FROM nlq.conversations;

SELECT COUNT(*) AS conversations_with_buyer_more_messages
FROM nlq.conversations
WHERE buyer_message_count > seller_message_count;

SELECT round(100.0 * SUM(CASE WHEN rating = 5 THEN 1 ELSE 0 END) / COUNT(*), 2) AS pct_5_star_reviews
FROM nlq.reviews
WHERE reviewer_role = 'buyer';

SELECT round(100.0 * SUM(CASE WHEN status = 'removed' THEN 1 ELSE 0 END) / COUNT(*), 2) AS removed_percentage
FROM nlq.listings_all
WHERE condition = 'good';

SELECT round(100.0 * COUNT(*) FILTER (WHERE (resolved_at - filed_at) <= INTERVAL '48 hours')::numeric / NULLIF(COUNT(*),0), 2) AS pct_within_48h
FROM nlq.reports
WHERE status = 'resolved';

SELECT ROUND(100.0 * AVG(CASE WHEN rating >= 4.5 THEN 1 ELSE 0 END)::numeric, 2) AS avg_rating_45_plus_percent
FROM nlq.reviews
WHERE reviewer_role = 'buyer';

select count(*) as listings_saved_by_at_least_5_students_never_sold
from (
  select s.item_id, count(distinct s.student_id) as saved_count
  from nlq.saved_items s
  group by s.item_id
) sub
where saved_count >= 5
  and not exists (select 1 from nlq.deals d where d.item_id = sub.item_id and d.deal_type = 'sale' and d.status = 'completed');
